# Static table rows provide a no-JavaScript fallback for the primary verified standings.
static_rows=[]
for i,r in enumerate(stats_rows):
    cl='zone-champ' if i<4 else 'zone-releg' if i>=17 else ''
    label='<span class="zone-label">UCL</span>' if i<4 else '<span class="zone-label europa">UEL</span>' if i<6 else '<span class="zone-label conference">UECL-Q</span>' if i==6 else '<span class="zone-label releg">RELEG.</span>' if i>=17 else ''
    history=sorted([m for m in finished if r['team'] in (m['home_team'],m['away_team'])],key=lambda m:(m['date'],m['kickoff_local']))[-5:]
    form=''.join(f"<i class=\"{('W' if (int(m['home_goals'])>int(m['away_goals']) if m['home_team']==r['team'] else int(m['away_goals'])>int(m['home_goals'])) else 'D' if int(m['home_goals'])==int(m['away_goals']) else 'L')}\">{('W' if (int(m['home_goals'])>int(m['away_goals']) if m['home_team']==r['team'] else int(m['away_goals'])>int(m['home_goals'])) else 'D' if int(m['home_goals'])==int(m['away_goals']) else 'L')}</i>" for m in history)
    static_rows.append(f"<tr class=\"{cl}\"><td>{i+1}</td><td class=\"team-name\">{r['team']}{label}</td><td>{r['P']}</td><td>{r['W']}</td><td>{r['D']}</td><td>{r['L']}</td><td>{r['GF']}</td><td>{r['GA']}</td><td>{'+' if r['GD']>0 else ''}{r['GD']}</td><td><b>{r['PTS']}</b></td><td><div class=\"form\">{form or '—'}</div></td></tr>")
page=page.replace('<tbody></tbody>','<tbody>'+''.join(static_rows)+'</tbody>')
